SELECT  FROM t_console_resource r
LEFT JOIN t_permission p ON p.permission_id=r.permission_id WHERE r.channel='OPERATIONS'
ORDER BY r.resource_id LIMIT #{limit}

SELECT  FROM t_console_resource r
LEFT JOIN t_permission p ON p.permission_id=r.permission_id
WHERE r.channel='OPERATIONS' AND r.resource_code=#{code}
